WITH lines AS (SELECT order_id,SUM(quantity*unit_price_cents) AS cents FROM order_items GROUP BY order_id), pay AS (SELECT order_id,SUM(amount_cents) AS cents FROM payments GROUP BY order_id) SELECT o.order_id,o.status,COALESCE(l.cents,0) AS item_cents,COALESCE(p.cents,0) AS paid_cents,MAX(COALESCE(l.cents,0)-COALESCE(p.cents,0),0) AS due_cents FROM orders o LEFT JOIN lines l ON l.order_id=o.order_id LEFT JOIN pay p ON p.order_id=o.order_id ORDER BY o.order_id;
